def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0

    if not alive:
        return min(budget, 20)

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive:
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= DAILY_SALARY * 4:
            rich_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None and prev.get('error') in (None, '', False):
            prev_bids.append(prev.get('bid', 0))

    n_players = len(alive) + 1
    approx_units = max(1, int(supply // WATER_REQ))
    scarcity = n_players - approx_units

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = 0
        avg_prev = 0

    if hp <= 2 or no_water >= 1:
        base = DAILY_SALARY * 0.92
    elif hp <= 4:
        base = DAILY_SALARY * 0.72
    else:
        base = DAILY_SALARY * 0.48

    if scarcity >= 2:
        base += 12
    elif scarcity <= 0:
        base -= 10

    base += min(10, desperate_count * 2)
    base += min(6, rich_count)

    if highest_prev >= DAILY_SALARY * 0.9:
        if hp > 4 and no_water == 0:
            bid = DAILY_SALARY * 0.28
        else:
            bid = max(base, highest_prev + 1)
    elif highest_prev >= DAILY_SALARY * 0.65:
        bid = max(base, avg_prev + 2)
    elif highest_prev > 0:
        bid = max(base, highest_prev + 1.5)
    else:
        bid = base

    if supply >= 24 and hp > 4 and no_water == 0:
        bid *= 0.75
    elif supply <= 16:
        bid *= 1.12

    if budget < DAILY_SALARY:
        bid = min(bid, max(8, budget * 0.7))

    if hp <= 2:
        bid = max(bid, DAILY_SALARY * 0.9)

    bid = max(0, min(budget, round(bid, 2)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    alive_opponents = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opponents:
        return max(0.0, min(float(my_status.get('budget', 0.0)), DAILY_SALARY * 0.45))

    prev_bids = []
    prev_hp_after = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid', 0.0)))
            except Exception:
                pass
            try:
                prev_hp_after.append(float(prev.get('hp_after', opp.get('hp', 0.0))))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = sum(prev_bids) / float(len(prev_bids)) if prev_bids else 0.0

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))

    # Determine target aggressiveness based on yesterday pressure.
    # If someone overreached near our salary, assume they are desperate -> we conserve.
    overbid_threshold = DAILY_SALARY * 0.85

    # Estimate how much water we need relative to expected supply.
    # If supply is tight, we bid more; if abundant, bid less.
    tightness = 0.0
    if supply <= float(WATER_REQ):
        tightness = 1.0
    elif supply <= float(MIN_SUPPLY):
        tightness = 0.75
    elif supply <= float(MAX_SUPPLY):
        tightness = 0.5
    else:
        tightness = 0.25

    if my_hp <= 2.0:
        # Critical: secure water at almost any reasonable cost.
        base = DAILY_SALARY * (0.88 if highest_prev_bid < overbid_threshold else 0.95)
    else:
        if highest_prev_bid >= overbid_threshold:
            # Opponents likely desperate; avoid price war.
            base = DAILY_SALARY * (0.25 + 0.25 * tightness)
        else:
            # Match slightly above average/leader to win without overspending.
            # Use a small increment over avg and leader to exploit their likely conservative bidding.
            base = max(DAILY_SALARY * (0.35 + 0.25 * tightness), avg_prev_bid + 2.0)
            if highest_prev_bid > 0.0:
                base = min(base, highest_prev_bid + 5.0)

    # Final clamp to budget.
    bid = max(0.0, min(my_budget, base))

    # If budget is extremely low, still bid enough to avoid wasting the day.
    if my_budget < DAILY_SALARY * 0.15:
        bid = max(0.0, min(my_budget, DAILY_SALARY * 0.12))

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    total_known_demand = WATER_REQ
    for opp in alive_opponents:
        total_known_demand += opp['water_requirement']

    bid = DAILY_SALARY * 0.5

    if supply < total_known_demand:
        shortfall_ratio = total_known_demand / supply
        if shortfall_ratio >= 2:
            bid = DAILY_SALARY * 0.95
        elif shortfall_ratio >= 1.5:
            bid = DAILY_SALARY * 0.8
        else:
            bid = DAILY_SALARY * 0.7
    else:
        surplus_ratio = supply / total_known_demand
        if surplus_ratio >= 2:
            bid = DAILY_SALARY * 0.3
        elif surplus_ratio >= 1.5:
            bid = DAILY_SALARY * 0.4
        else:
            bid = DAILY_SALARY * 0.5

    if my_status['hp'] <= 2:
        bid = max(bid, DAILY_SALARY * 0.9)
    elif my_status['hp'] <= 4:
        bid = max(bid, DAILY_SALARY * 0.75)

    return min(my_status['budget'], bid)

